import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        reader = csv.reader(io.StringIO(raw_csv, newline=""))
        try:
            columns = next(reader)
        except StopIteration:
            return {"columns": [], "rows": []}
        rows = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    if columns:
        columns[0] = columns[0].removeprefix("\ufeff")

    width = max([len(columns)] + [len(row) for row in rows])
    used_names = set(columns)
    while len(columns) < width:
        index = len(columns) + 1
        name = "extra_column_{}".format(index)
        while name in used_names:
            index += 1
            name = "extra_column_{}".format(index)
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
